python3 -c "
import csv
import io

# Read the April 2025 file
with open('/root/weo_apr2025.xls', 'r', encoding='utf-16-le') as f:
    content = f.read()

reader = csv.reader(io.StringIO(content), delimiter='\t')
header = next(reader)

# Find column indices for years 2000-2030
year_cols = {}
for i, col in enumerate(header):
    col = col.strip()
    if col.isdigit() and 2000 <= int(col) <= 2030:
        year_cols[int(col)] = i

# Find Georgia rows for NGDP_R and NGDP_RPCH
ngdp_r = {}
ngdp_rpch = {}
for row in reader:
    if len(row) > 3:
        weo_code = row[0].strip()
        subject = row[2].strip()
        if weo_code == '915' and subject in ('NGDP_R', 'NGDP_RPCH'):
            units = row[6].strip() if len(row) > 6 else 'N/A'
            scale = row[7].strip() if len(row) > 7 else 'N/A'
            if subject == 'NGDP_R':
                print(f'NGDP_R Units: {units}, Scale: {scale}')
            else:
                print(f'NGDP_RPCH Units: {units}, Scale: {scale}')
            for year in range(2000, 2031):
                if year in year_cols:
                    idx = year_cols[year]
                    val = row[idx].strip() if idx < len(row) else 'n/a'
                    val = val.replace(',', '')
                    if subject == 'NGDP_R':
                        ngdp_r[year] = val
                    else:
                        ngdp_rpch[year] = val

# Print results
print(f'')
print(f'Source: IMF World Economic Outlook, April 2025')
print(f'Country: Georgia (WEO code 915)')
print(f'')
print(f'NGDP_R: Gross domestic product, constant prices (Billions of national currency)')
print(f'NGDP_RPCH: Gross domestic product, constant prices (Percent change)')
print(f'')
print(f'Year, NGDP_R, NGDP_RPCH')
for year in range(2000, 2031):
    r_val = ngdp_r.get(year, 'n/a')
    rpch_val = ngdp_rpch.get(year, 'n/a')
    if r_val != 'n/a' or rpch_val != 'n/a':
        print(f'{year}, {r_val}, {rpch_val}')
